#include <concepts>
#include <iostream>

template <typename T>
concept Container = requires(T c) {
    typename T::value_type; // Type requirement
    { c.size() } -> std::same_as<std::size_t>; // Compound requirement
    requires sizeof(T) >= 8; // Nested requirement
};

template <typename T>
concept Clearable = requires(T x) {
    x.___(); // Simple requirement
};

template <typename T>
concept LargeType = requires {
    ___ sizeof(T) > 16; // Nested requirement
};

template <typename T>
requires std::integral<T> ___ std::signed_integral<T>
void handleSigned(T val) {}

template <typename T>
requires std::integral<T> ___ std::floating_point<T>
void processNumber(T n) {}
